sys_script_include.script:
var IncentNowStatementHelper = Class.create();
IncentNowStatementHelper.prototype = {

    initialize: function() {},

    // ==========================================
    // MAIN API - QTD / YTD
    // ==========================================
  getQTDAndYTD: function(user, periodId) {

    var result = {
        qtd_commission: 0,
        ytd_commission: 0
    };

    if (!user || !periodId)
        return result;

    var periodGR = new GlideRecordSecure('x_ctans_incentnow_fiscal_period');

    if (!periodGR.get(periodId))
        return result;

    var fiscalYear = periodGR.getValue('fiscal_year');
    var periodStart = periodGR.getValue('period_start_date');
    var periodEnd = periodGR.getValue('period_end_date');

    if (!fiscalYear || !periodStart || !periodEnd)
        return result;

    // YTD does not need a Year Fiscal Period record.
    result.ytd_commission = this._sumYTDCommission(
        user,
        fiscalYear,
        periodEnd
    );

    // Find quarter containing selected month.
    var quarterStart = this._getParentStart(
        new GlideDateTime(periodStart),
        new GlideDateTime(periodEnd),
        'quarter'
    );

    if (quarterStart) {
        result.qtd_commission = this._sumQTDCommission(
            user,
            fiscalYear,
            quarterStart,
            periodEnd
        );
    } else {
        // Defensive fallback:
        // at minimum current month's commission should be shown.
        result.qtd_commission = this._getPeriodCommission(
            user,
            periodId
        );
    }

    return result;
},

_sumYTDCommission: function(user, fiscalYear, endDate) {

    if (!user || !fiscalYear || !endDate)
        return 0;

    var total = 0;
    var statementGR = new GlideRecordSecure('x_ctans_incentnow_incentive_statement');

    statementGR.addQuery('user', user);
    statementGR.addQuery('fiscal_year', fiscalYear);
    statementGR.addQuery('fiscal_period.period_type', 'month');
    statementGR.addQuery('fiscal_period.period_end_date', '<=', endDate);
    statementGR.query();

    while (statementGR.next())
        total += parseFloat(statementGR.getValue('total_commission')) || 0;

    return parseFloat(total.toFixed(2));
},

_sumQTDCommission: function(user, fiscalYear, quarterStart, endDate) {

    if (!user || !fiscalYear || !quarterStart || !endDate)
        return 0;

    var total = 0;
    var statementGR = new GlideRecordSecure('x_ctans_incentnow_incentive_statement');

    statementGR.addQuery('user', user);
    statementGR.addQuery('fiscal_year', fiscalYear);
    statementGR.addQuery('fiscal_period.period_type', 'month');
    statementGR.addQuery('fiscal_period.period_start_date', '>=', quarterStart);
    statementGR.addQuery('fiscal_period.period_end_date', '<=', endDate);
    statementGR.query();

    while (statementGR.next())
        total += parseFloat(statementGR.getValue('total_commission')) || 0;

    return parseFloat(total.toFixed(2));
},

_getParentStart: function(start, end, type) {

    var fiscalPeriodGR = new GlideRecordSecure('x_ctans_incentnow_fiscal_period');

    fiscalPeriodGR.addQuery('period_type', type);
    fiscalPeriodGR.addQuery('period_start_date', '<=', end);
    fiscalPeriodGR.addQuery('period_end_date', '>=', start);
    fiscalPeriodGR.setLimit(1);
    fiscalPeriodGR.query();

    if (fiscalPeriodGR.next())
        return fiscalPeriodGR.getValue('period_start_date');

    return '';
},

_getPeriodCommission: function(user, periodId) {

    if (!user || !periodId)
        return 0;

    var total = 0;
    var statementGR = new GlideRecordSecure('x_ctans_incentnow_incentive_statement');

    statementGR.addQuery('user', user);
    statementGR.addQuery('fiscal_period', periodId);
    statementGR.setLimit(1);
    statementGR.query();

    if (statementGR.next())
        total = parseFloat(statementGR.getValue('total_commission')) || 0;

    return total;
},
getPeriodChange: function(user, periodId) {

    var result = {
        change_percentage: 0,
        previous_commission: 0
    };

    if (!user || !periodId)
        return result;

    var periodGR = new GlideRecordSecure('x_ctans_incentnow_fiscal_period');

    if (!periodGR.get(periodId))
        return result;

    var currentCommission = this._getPeriodCommission(user, periodId);

    var prevGR = new GlideRecordSecure('x_ctans_incentnow_fiscal_period');
    prevGR.addQuery('period_type', periodGR.getValue('period_type'));
    prevGR.addQuery('fiscal_year', periodGR.getValue('fiscal_year'));
    prevGR.addQuery('period_end_date', '<', periodGR.getValue('period_start_date'));
    prevGR.orderByDesc('period_end_date');
    prevGR.setLimit(1);
    prevGR.query();

    if (!prevGR.next())
        return result;

    var previousCommission = this._getPeriodCommission(user, prevGR.getUniqueValue());

    result.previous_commission = previousCommission;

    if (previousCommission > 0) {
        var change = ((currentCommission - previousCommission) / previousCommission) * 100;
        result.change_percentage = parseFloat(change.toFixed(2));
    }

    return result;
},
    // ==========================================
    // EXISTING SINGLE PLAN HTML
    // ==========================================
    buildStatementHTML: function(steps, meta) {

        var html = '';

        html += '<div class="statement-wrapper">';
        html += '<h2 class="statement-title" style="display:flex; align-items:center; gap:10px;">Incentive Statement</h2>';

        html += '<table class="statement-header-table">';
        html += '<tr class="header-row user-row"><td><b class="b headu">User:</b></td><td>' + this._safe(meta.user) + '</td></tr>';
        html += '<tr class="header-row plan-row"><td><b class="b">Plan:</b></td><td>' + this._safe(meta.plan) + '</td></tr>';
        html += '<tr class="header-row period-row"><td><b class="b">Fiscal Period:</b></td><td>' + this._safe(meta.period) + '</td></tr>';
        html += '<tr class="header-row generated-row"><td><b class="b">Generated On:</b></td><td>' + this._safe(meta.generatedOn) + '</td></tr>';
        html += '<tr class="header-row quota-row"><td><b class="b">Target Quota:</b></td><td>' + this._safe(meta.quota) + '</td></tr>';
        html += '<tr class="header-row total-row"><td><b class="b">Total Commission:</b></td><td><b>' + this._safe(meta.total) + '</b></td></tr>';
        html += '</table>';

        if (meta.earningRules && meta.earningRules.length > 0)
            html += this._buildEarningRulesHTML(meta.earningRules);

        html += this._buildPayoutHTML(steps, meta.total);
        html += '</div>';

        return html;
    },

    _buildEarningRulesHTML: function(earningRules) {

        var html = '';

        html += '<table class="earning-rules-table">';
        html += '<tr class="earning-rules-header" style="padding:2rem;">' +
            '<th class="earning-rule-col">Earning Rule</th>' +
            '<th class="earning-object-col">Object</th>' +
            '<th class="earning-field-col">Field</th>' +
            '<th class="earning-type-col">Type</th>' +
            '<th class="earning-level-col">Earning Level</th>' +
            '<th class="earning-condition-col">Rule Condition</th>' +
            '<th class="earning-value-col">Value</th>' +
            '</tr>';

        for (var i = 0; i < earningRules.length; i++) {
            html += '<tr class="earning-rule-row">' +
                '<td class="earning-rule-name">' + this._safe(earningRules[i].name) + '</td>' +
                '<td class="earning-rule-object">' + this._safe(earningRules[i].object || '-') + '</td>' +
                '<td class="earning-rule-field">' + this._safe(earningRules[i].field || '-') + '</td>' +
                '<td class="earning-rule-type">' + this._safe(earningRules[i].type || '-') + '</td>' +
                '<td class="earning-rule-level">' + this._safe(earningRules[i].earning_level || '-') + '</td>' +
                '<td class="earning-rule-condition">' + this._safe(earningRules[i].condition || '-') + '</td>' +
                '<td class="earning-rule-value">' + this._safe(earningRules[i].value || '-') + '</td>' +
                '</tr>';
        }

        html += '</table>';

        return html;
    },

    _buildPayoutHTML: function(steps, total) {

        var html = '';

        html += '<table class="payout-table">';
        html += '<tr class="payout-header" style="padding:2rem;">' +
            '<th class="payout-component-col">Payout Component(s)</th>' +
            '<th class="payout-value-col">Commission</th>' +
            '</tr>';

        for (var i = 0; i < steps.length; i++) {

            var step = steps[i];

            html += '<tr class="payout-row">' +
                '<td class="payout-detail">' +
                '<div class="payout-rule-name">' + this._safe(step.ruleName) + '</div>' +
                '<div class="payout-trace">';

            if (step.trace)
                html += this._buildTraceHTML(step.trace);

            html += '</div></td>' +
                '<td class="payout-amount">' + this._safe(step.payoutValue) + '</td>' +
                '</tr>';
        }

        html += '<tr class="payout-total-row">' +
            '<td class="payout-total-label">Total</td>' +
            '<td class="payout-total-value">' + this._safe(total) + '</td>' +
            '</tr>';

        html += '</table>';

        return html;
    },

    _buildTraceHTML: function(trace) {

        var html = '';

        for (var j = 0; j < trace.length; j++) {

            var t = trace[j];

            if (t.type == 'earning') {
                html += '<div class="trace-earning"><b>Earning:</b> ' +
                    this._safe(t.name) + ' → ' + this._safe(t.value) + '</div>';
            }

            if (t.type == 'lookup') {
                html += '<div class="trace-lookup"><b>Lookup:</b> ' +
                    this._safe(t.name) + ' → ' + this._safe(t.output) + '</div>';
            }

            if (t.type == 'calculation' && j === trace.length - 1) {
                html += '<div class="trace-calculation"><b>Calculation:</b> ' +
                    this._safe(t.formula) + ' = ' + this._safe(t.result) + '</div>';
            }
        }

        return html;
    },

    _safe: function(val) {

        if (val == null || val == undefined)
            return '';

        return (val + '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');
    },

    // ==========================================
    // CONSOLIDATED STATEMENT HTML
    // ==========================================
    buildConsolidatedStatementHTML: function(planResults, meta) {

        var html = '';
        planResults = planResults || [];

        html += '<div class="statement-wrapper">';
        html += '<h2 class="statement-title" style="display:flex; align-items:center; gap:10px;">Incentive Statement</h2>';

        html += '<table class="statement-header-table">';
        html += '<tr class="header-row user-row"><td><b>User:</b></td><td>' + this._safe(meta.user) + '</td></tr>';
        html += '<tr class="header-row period-row"><td><b>Fiscal Period:</b></td><td>' + this._safe(meta.period) + '</td></tr>';
        html += '<tr class="header-row plan-row"><td><b>Plans:</b></td><td>' + this._safe(meta.plans) + '</td></tr>';
        html += '<tr class="header-row generated-row"><td><b>Generated On:</b></td><td>' + this._safe(meta.generatedOn) + '</td></tr>';
        html += '</table>';

        for (var i = 0; i < planResults.length; i++) {

            var plan = planResults[i];

            html += '<div class="statement-plan-section" style="margin-top:30px;">';
            html += '<h3 class="statement-plan-title">' + this._safe(plan.planName) + '</h3>';

            if (plan.quotaResults && plan.quotaResults.length > 0)
                html += this._buildQuotaResultsHTML(plan.quotaResults);

            if (plan.earningRules && plan.earningRules.length > 0)
                html += this._buildEarningRulesHTML(plan.earningRules);

            html += this._buildPayoutHTML(plan.payoutBreakdown || [], plan.formattedTotal);
            html += '</div>';
        }

        html += '<table class="statement-header-table" style="margin-top:30px;">';
        html += '<tr class="payout-total-row"><td><b>Total Commission</b></td><td><b>' +
            this._safe(meta.total) + '</b></td></tr>';
        html += '</table>';

        html += '</div>';

        return html;
    },

    _buildQuotaResultsHTML: function(quotaResults) {

        var html = '';

        html += '<table class="quota-results-table">';
        html += '<tr class="quota-results-header">' +
            '<th>Attainment Lookup Rule</th>' +
            '<th>Quota</th>' +
            '<th>Target</th>' +
            '<th>Achievement</th>' +
            '<th>Attainment</th>' +
            '</tr>';

        for (var i = 0; i < quotaResults.length; i++) {

            var quota = quotaResults[i];

            html += '<tr class="quota-result-row">' +
                '<td>' + this._safe(quota.lookupRule) + '</td>' +
                '<td>' + this._safe(quota.quota) + '</td>' +
                '<td>' + this._safe(quota.target) + '</td>' +
                '<td>' + this._safe(quota.achievement) + '</td>' +
                '<td>' + this._safe(quota.attainment) + '%</td>' +
                '</tr>';
        }

        html += '</table>';

        return html;
    },

    type: 'IncentNowStatementHelper'
};
